package com.enerlution.ems.business;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.enerlution.ems.auth.AccessControl;
import com.enerlution.ems.common.BusinessException;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
class StationHistoryServiceTest {
 @Test void deniedExportNeverReads(){var db=mock(JdbcTemplate.class);var a=mock(AccessControl.class);doThrow(new BusinessException(403,"denied")).when(a).requireStationPermission(21,"report.export");assertThrows(BusinessException.class,()->new StationHistoryService(new DomainSupport(db,a)).export(21,"day","2026-01-01"));verifyNoInteractions(db);}

 @Test void mockIsExplicitAndOnlyFallback(){var db=mock(JdbcTemplate.class);when(db.queryForList(contains("FROM station st"),eq(21L))).thenReturn(List.of(Map.of("timezone","Asia/Shanghai")));when(db.queryForList(contains("FROM station_history_mock_dataset"),eq(21L),eq("day"),eq("2026-01-01"))).thenReturn(List.of(Map.of("timezone","Asia/Shanghai","created_at",java.sql.Timestamp.from(java.time.Instant.parse("2026-01-02T00:00:00Z")),"payload","{}")));var service=new StationHistoryService(new DomainSupport(db,mock(AccessControl.class)));assertEquals("database-mock",service.read(21,"day","2026-01-01").source());when(db.queryForList(contains("FROM station_reference_history_capture"),eq(21L),eq("day"),eq("2026-01-01"))).thenReturn(List.of(Map.of("timezone","Asia/Shanghai","captured_at",java.sql.Timestamp.from(java.time.Instant.parse("2026-01-02T00:00:00Z")),"payload","{}")));assertEquals("reference-capture",service.read(21,"day","2026-01-01").source());}
 @Test void weekUsesAnExplicitLastDay(){assertDoesNotThrow(()->StationHistoryService.validate("week","2026-01-08"));assertThrows(BusinessException.class,()->StationHistoryService.validate("week","2026-02-30"));}
 @Test void deniedAssetNeverReads(){var db=mock(JdbcTemplate.class);var a=mock(AccessControl.class);doThrow(new BusinessException(403,"denied")).when(a).requireStationPermission(21,"asset.read");assertThrows(BusinessException.class,()->new StationHistoryService(new DomainSupport(db,a)).read(21,"day","2026-01-01"));verifyNoInteractions(db);}
 @Test void revokedTelemetryAtBoundaryFails(){var db=mock(JdbcTemplate.class);var a=mock(AccessControl.class);when(db.queryForList(contains("FROM station st"),eq(21L))).thenReturn(List.of(Map.of("timezone","Asia/Shanghai")));doNothing().doThrow(new BusinessException(403,"revoked")).when(a).requireStationPermission(21,"telemetry.read");assertEquals(403,assertThrows(BusinessException.class,()->new StationHistoryService(new DomainSupport(db,a)).read(21,"day","2026-01-01")).status());}
 @Test void offsetTimestampNormalizesWithoutLosingInstant(){assertEquals("2026-01-02T00:00:00Z",StationHistoryService.capturedAt(java.time.OffsetDateTime.parse("2026-01-02T08:00:00+08:00")));assertThrows(IllegalArgumentException.class,()->StationHistoryService.capturedAt("2026-01-02 08:00:00"));}
 @Test void strictPeriods(){assertDoesNotThrow(()->StationHistoryService.validate("day","2024-02-29"));for(String date:List.of("2025-02-29","2026-1-01","2030-01-01"))assertThrows(BusinessException.class,()->StationHistoryService.validate("day",date));assertThrows(BusinessException.class,()->StationHistoryService.validate("total","2026:2025"));}
 @Test void deniedTelemetryNeverReads(){var db=mock(JdbcTemplate.class);var a=mock(AccessControl.class);doThrow(new BusinessException(403,"denied")).when(a).requireStationPermission(21,"telemetry.read");assertThrows(BusinessException.class,()->new StationHistoryService(new DomainSupport(db,a)).read(21,"day","2026-01-01"));verifyNoInteractions(db);}
 @Test void archivedIsMissing(){var db=mock(JdbcTemplate.class);assertEquals(404,assertThrows(BusinessException.class,()->new StationHistoryService(new DomainSupport(db,mock(AccessControl.class))).read(21,"day","2026-01-01")).status());}
 @Test void missingAndCapturedAreDistinct(){var db=mock(JdbcTemplate.class);when(db.queryForList(contains("FROM station st"),eq(21L))).thenReturn(List.of(Map.of("timezone","Asia/Shanghai")));var service=new StationHistoryService(new DomainSupport(db,mock(AccessControl.class)));assertFalse(service.read(21,"day","2026-01-01").available());when(db.queryForList(contains("FROM station_reference_history_capture"),eq(21L),eq("day"),eq("2026-01-01"))).thenReturn(List.of(Map.of("timezone","Asia/Shanghai","captured_at",java.sql.Timestamp.from(java.time.Instant.parse("2026-01-02T00:00:00Z")),"payload","{\"zero\":0,\"text\":\"--\"}")));var result=service.read(21,"day","2026-01-01");assertTrue(result.available());assertEquals("2026-01-02T00:00:00Z",result.capturedAt());assertEquals(0,result.payload().get("zero").intValue());assertEquals("--",result.payload().get("text").textValue());}
}
